export const topicsBySlug: Record<string, Topic> = Object.fromEntries(
  topics.map((t) => [t.slug, t]),
);

export function getRelatedTopics(topic: Topic): Topic[] {
  return topic.relatedSlugs
    .map((s) => topicsBySlug[s])
    .filter(Boolean);
}
